/*!50003 CREATE*/ /*!50017 DEFINER=`sa`@`%`*/ /*!50003 TRIGGER utrigger_Rera_QUpdatesProject_EventRecord_INSERT
AFTER INSERT ON tbl_rera_project_quarterlyupdate_eventaction
FOR EACH ROW
BEGIN      
     DECLARE v_PromoterId BigInt; 
     Declare v_ProjectId BigInt;
     Declare v_QuarterName varchar(100);
     Declare v_QuarterYear int;
     Declare v_ProjectDiaryNumber varchar(100); 
     Declare v_QUpdatesDiaryNumber varchar(100);
     Declare v_RegistrationNumber varchar(100);
     Declare v_EventType int;   
       
       SET v_ProjectId=NEW.Related_Project_ID;         
       SET v_PromoterId=NEW.Related_Promoter_ID;  
       SET v_QuarterName=NEW.Related_QUpdateProject_QuarterName;
	   SET v_QuarterYear=NEW.Related_QUpdateProject_Year;
       SET v_ProjectDiaryNumber=NEW.DiaryNumber_Promoter;
       SET v_QUpdatesDiaryNumber=NEW.DiaryNumber_QUpdateProject;
       SET v_RegistrationNumber=NEW.DiaryNumber_Project;
       SET v_EventType=NEW.EventAction_Type;


 -- Activate ReApply Details          
 If v_EventType = 160007   
 then      
    update tbl_rera_project_quarterlyupdate_regdiarynumber set IsDraft=0, IsLock=0 where PromoterID=v_PromoterId and ProjectID=v_ProjectId and QUpdateProject_Year=v_QuarterYear and QUpdateProject_QuarterName=v_QuarterName and IsActive=1;
   
    update tbl_rera_project_quarterlyupdate_inventory set IsDraft=4, IsLock=0 where Related_ProjectRegistration_ID=v_ProjectId and QUpdateInventory_Year=v_QuarterYear and QUpdateInventory_QuarterName=v_QuarterName and IsActive=1 and IsDraft=5;
    update tbl_rera_project_quarterlyupdate_parkingdetails set IsDraft=4, IsLock=0 where Related_ParkingProjectRegistration_ID=v_ProjectId and QUpdateParking_Year=v_QuarterYear and QUpdateParking_QuarterName=v_QuarterName and IsActive=1 and IsDraft=5;
    update tbl_rera_project_quarterlyupdate_constructionstatusphotographs set IsDraft=4, IsLock=0 where ProjectPhotographsRelated_Project_ID=v_ProjectId and Related_Promoter_ID=v_PromoterId and QUpdatePhotographs_Year=v_QuarterYear and QUpdatePhotographs_QuarterName=v_QuarterName and IsActive=1 and IsDraft=5;
    update tbl_rera_project_quarterlyupdate_internalfacilities set IsDraft=4, IsLock=0 where ProjectInfrastructureFacilitiesRelated_ProjectRegistration_ID=v_ProjectId and QUpdateInfraFacilities_Year=v_QuarterYear and QUpdateInfraFacilities_QuarterName=v_QuarterName and IsActive=1 and IsDraft=5;
    update tbl_rera_project_quarterlyupdate_externalfacilities set IsDraft=4, IsLock=0 where ProjectInfrastructureFacilitiesRelated_ProjectRegistration_ID=v_ProjectId and QUpdateInfraExFacilities_Year=v_QuarterYear and QUpdateInfraExFacilities_QuarterName=v_QuarterName and IsActive=1 and IsDraft=5;
    update tbl_rera_project_quarterlyupdate_approvaldetails set IsDraft=4, IsLock=0 where Related_ApprovalProjectRegistration_ID=v_ProjectId and QUpdateApproval_Year=v_QuarterYear and QUpdateApproval_QuarterName=v_QuarterName and IsActive=1 and IsDraft=5;
 
 end if;
 
 -- No Reply Found from Promoter  
 If v_EventType = 160020  
 then      
 	update tbl_rera_project_quarterlyupdate_regdiarynumber set IsDraft=1, IsLock=1 where PromoterID=v_PromoterId and ProjectID=v_ProjectId and QUpdateProject_Year=v_QuarterYear and QUpdateProject_QuarterName=v_QuarterName and IsActive=1;
    
    update tbl_rera_project_quarterlyupdate_inventory set IsDraft=1, IsLock=1 where Related_ProjectRegistration_ID=v_ProjectId and QUpdateInventory_Year=v_QuarterYear and QUpdateInventory_QuarterName=v_QuarterName and IsActive=1 and IsDraft in (0,4,5);
    update tbl_rera_project_quarterlyupdate_parkingdetails set IsDraft=1, IsLock=1 where Related_ParkingProjectRegistration_ID=v_ProjectId and QUpdateParking_Year=v_QuarterYear and QUpdateParking_QuarterName=v_QuarterName and IsActive=1 and IsDraft in (0,4,5);
    update tbl_rera_project_quarterlyupdate_constructionstatusphotographs set IsDraft=1, IsLock=1 where ProjectPhotographsRelated_Project_ID=v_ProjectId and Related_Promoter_ID=v_PromoterId and QUpdatePhotographs_Year=v_QuarterYear and QUpdatePhotographs_QuarterName=v_QuarterName and IsActive=1 and IsDraft in (0,4,5);
    update tbl_rera_project_quarterlyupdate_internalfacilities set IsDraft=1, IsLock=1 where ProjectInfrastructureFacilitiesRelated_ProjectRegistration_ID=v_ProjectId and QUpdateInfraFacilities_Year=v_QuarterYear and QUpdateInfraFacilities_QuarterName=v_QuarterName and IsActive=1 and IsDraft in (0,4,5);
    update tbl_rera_project_quarterlyupdate_externalfacilities set IsDraft=1, IsLock=1 where ProjectInfrastructureFacilitiesRelated_ProjectRegistration_ID=v_ProjectId and QUpdateInfraExFacilities_Year=v_QuarterYear and QUpdateInfraExFacilities_QuarterName=v_QuarterName and IsActive=1 and IsDraft in (0,4,5);
    update tbl_rera_project_quarterlyupdate_approvaldetails set IsDraft=1, IsLock=1 where Related_ApprovalProjectRegistration_ID=v_ProjectId and QUpdateApproval_Year=v_QuarterYear and QUpdateApproval_QuarterName=v_QuarterName and IsActive=1 and IsDraft in (0,4,5);

 end if;  
 
 
 END */;;
